# Delete old notes
old_notes = glob.glob(os.path.join(base_dir, "*.md"))
for old in old_notes:
    os.remove(old)

# Write new notes
for note in new_notes:
    note_path = os.path.join(base_dir, f"{note['title']}.md")
    
    frontmatter = "---\n"
    frontmatter += f"title: \"{note['title']}\"\n"
    frontmatter += f"tags: [{', '.join(note['tags'])}]\n"
    frontmatter += "---\n\n"
    
    with open(note_path, "w", encoding="utf-8") as f:
        f.write(frontmatter + note['content'])
        f.write(f"\n\n---\n> [!link] 関連リソース\n> - [[{moc_file}|📁 研究アーカイブ目次 (MOC)]]\n")
        
print(f"Expanded to {len(new_notes)} detailed notes in Awa Theory directory.")
